import type {TopicDeepening} from './topicDeepening';
/** Original, fictional topic lessons. Language-specific grammar notes are not interchangeable. */
export const topicDeepeningMore:readonly TopicDeepening[]=[
{id:'passive-process',level:'b2',section:'foundation',number:9,title:'مجهول در گزارش مراحل',passage:{
fr:'Une association a reçu vingt demandes pour un atelier. Hier, chaque dossier a été vérifié par une bénévole. Les candidats retenus sont informés aujourd’hui par courrier électronique. Les inscriptions seront confirmées vendredi après la réception des réponses. Trois dossiers restent incomplets : leurs auteurs ont été invités à fournir les documents manquants avant jeudi. La coordinatrice explique que le nombre de places est limité et que les données ne seront conservées que pendant la durée nécessaire à l’organisation. Une liste d’attente sera préparée si tous les candidats ne peuvent pas participer.',
de:'Ein Verein hat zwanzig Anmeldungen für einen Workshop erhalten. Gestern wurde jede Bewerbung von einer Freiwilligen geprüft. Die ausgewählten Personen werden heute per E-Mail informiert. Die Anmeldungen werden am Freitag bestätigt, nachdem die Antworten eingegangen sind. Drei Bewerbungen sind noch unvollständig: Die betreffenden Personen wurden gebeten, die fehlenden Unterlagen bis Donnerstag einzureichen. Die Koordinatorin erklärt, dass die Plätze begrenzt sind und die Daten nur so lange gespeichert werden, wie es für die Organisation nötig ist. Eine Warteliste wird erstellt, falls nicht alle teilnehmen können.',
es:'Una asociación ha recibido veinte solicitudes para un taller. Ayer cada expediente fue revisado por una voluntaria. Las personas seleccionadas son informadas hoy por correo electrónico. Las inscripciones serán confirmadas el viernes después de recibir las respuestas. Tres expedientes siguen incompletos: se ha pedido a sus autores que entreguen los documentos que faltan antes del jueves. La coordinadora explica que las plazas son limitadas y que los datos se conservarán solo durante el tiempo necesario para la organización. Se preparará una lista de espera si no pueden participar todas las personas.'},
questions:[{prompt:'دیروز برای هر پرونده چه اتفاقی افتاد؟',choices:['توسط داوطلب بررسی شد','به همه بازگردانده شد','بدون بررسی تأیید شد'],correctIndex:0,explanation:'هر پرونده دیروز توسط یک داوطلب بررسی شد.',evidence:{fr:'chaque dossier a été vérifié par une bénévole',de:'jede Bewerbung von einer Freiwilligen geprüft',es:'cada expediente fue revisado por una voluntaria'}},{prompt:'چند پرونده هنوز ناقص‌اند؟',choices:['دو','سه','بیست'],correctIndex:1,explanation:'سه پرونده ناقص مانده‌اند.',evidence:{fr:'Trois dossiers restent incomplets',de:'Drei Bewerbungen sind noch unvollständig',es:'Tres expedientes siguen incompletos'}},{prompt:'ثبت‌نام‌ها چه زمانی تأیید می‌شوند؟',choices:['دیروز','پنجشنبه پیش از پاسخ','جمعه پس از دریافت پاسخ‌ها'],correctIndex:2,explanation:'تأیید برای جمعه بعد از دریافت پاسخ برنامه‌ریزی شده است.',evidence:{fr:'confirmées vendredi après la réception des réponses',de:'am Freitag bestätigt, nachdem die Antworten eingegangen sind',es:'confirmadas el viernes después de recibir las respuestas'}}],
notes:{fr:{explanation:'مجهول با être و participe passé ساخته می‌شود و زمان être زمان جمله را نشان می‌دهد. اسم انجام‌دهنده را در صورت اهمیت با par بیاورید؛ توافق participe را بررسی کنید.',first:'Les dossiers ont été vérifiés hier.',second:'Les inscriptions seront confirmées vendredi.',difference:'اولی عمل گذشته و دومی اقدام آینده را با تمرکز بر پرونده‌ها بیان می‌کند.',phrases:[{text:'un dossier incomplet',meaning:'پروندهٔ ناقص'},{text:'une liste d’attente',meaning:'فهرست انتظار'},{text:'confirmer une inscription',meaning:'تأیید ثبت‌نام'}]},de:{explanation:'مجهول فرایند با werden و Partizip II ساخته می‌شود؛ wurde گذشته، werden حال و werden … werden آینده را نشان می‌دهد. با von می‌توان عامل را ذکر کرد.',first:'Die Bewerbungen wurden gestern geprüft.',second:'Die Anmeldungen werden am Freitag bestätigt werden.',difference:'اولی گذشته و دومی آینده را بیان می‌کند؛ در آلمانی معمولاً حال همراه زمان آینده هم رایج است.',phrases:[{text:'eine unvollständige Bewerbung',meaning:'پروندهٔ ناقص'},{text:'eine Warteliste',meaning:'فهرست انتظار'},{text:'eine Anmeldung bestätigen',meaning:'تأیید ثبت‌نام'}]},es:{explanation:'مجهول با ser و participio ساخته می‌شود و فعل ser زمان را نشان می‌دهد؛ participio با اسم سازگار می‌شود. ساختار se نیز برای بیان عمل بدون ذکر عامل رایج است.',first:'Los expedientes fueron revisados ayer.',second:'Las inscripciones serán confirmadas el viernes.',difference:'اولی گذشته و دومی آینده را با تمرکز بر پرونده یا ثبت‌نام بیان می‌کند.',phrases:[{text:'un expediente incompleto',meaning:'پروندهٔ ناقص'},{text:'una lista de espera',meaning:'فهرست انتظار'},{text:'confirmar una inscripción',meaning:'تأیید ثبت‌نام'}]}},
speaking:'مراحل رسیدگی به درخواست را در گذشته، حال و آینده توضیح دهید؛ وقتی عامل مهم است او را نام ببرید.',writing:'گزارش کوتاهی برای داوطلبان بنویسید که کار انجام‌شده، وضعیت کنونی و اقدام بعدی را روشن کند.',steps:['تعداد درخواست و مرحلهٔ گذشته را بیان کنید.','وضعیت فعلی و پرونده‌های ناقص را شرح دهید.','موعد اقدام بعدی را بنویسید.','زمان و تطابق ساختار مجهول را بررسی کنید.'],model:{fr:'Les dossiers ont été vérifiés hier et les candidats retenus sont informés aujourd’hui. Trois dossiers sont encore incomplets ; leurs auteurs ont été invités à envoyer les documents manquants avant jeudi. Les inscriptions seront confirmées vendredi après réception des réponses. Une liste d’attente sera préparée si les places ne suffisent pas.',de:'Die Bewerbungen wurden gestern geprüft und die ausgewählten Personen werden heute informiert. Drei Bewerbungen sind noch unvollständig; die fehlenden Unterlagen sollen bis Donnerstag eingereicht werden. Die Anmeldungen werden am Freitag nach Eingang der Antworten bestätigt. Falls die Plätze nicht ausreichen, wird eine Warteliste erstellt.',es:'Los expedientes fueron revisados ayer y hoy se informa a las personas seleccionadas. Tres expedientes siguen incompletos y se ha pedido la documentación antes del jueves. Las inscripciones se confirmarán el viernes después de recibir las respuestas. Si las plazas no son suficientes, se preparará una lista de espera.'}},
{id:'causative-service',level:'b2',section:'foundation',number:10,title:'واگذاری تعمیر و اجازهٔ انجام کار',passage:{
fr:'Dans une école de musique, le piano de la salle principale ne fonctionne plus correctement. La directrice ne peut pas le réparer elle-même. Elle fait examiner l’instrument par une technicienne avant de décider des travaux. La technicienne constate que deux touches doivent être remplacées et remet un devis. La directrice laisse ensuite le responsable financier consulter le devis avant de l’accepter. Les cours continuent dans une autre salle pendant cette période. Si le coût dépasse le budget prévu, l’école demandera une deuxième estimation avant de faire effectuer la réparation.',
de:'In einer Musikschule funktioniert das Klavier im großen Raum nicht mehr richtig. Die Leiterin kann es nicht selbst reparieren. Sie lässt das Instrument von einer Technikerin untersuchen, bevor sie über die Arbeiten entscheidet. Die Technikerin stellt fest, dass zwei Tasten ersetzt werden müssen, und legt einen Kostenvoranschlag vor. Danach lässt die Leiterin den Finanzverantwortlichen den Kostenvoranschlag prüfen, bevor sie ihn annimmt. Währenddessen findet der Unterricht in einem anderen Raum statt. Falls die Kosten das geplante Budget überschreiten, holt die Schule eine zweite Schätzung ein, bevor sie die Reparatur durchführen lässt.',
es:'En una escuela de música, el piano de la sala principal ya no funciona bien. La directora no puede repararlo ella misma. Hace que una técnica examine el instrumento antes de decidir qué trabajos realizar. La técnica comprueba que hay que sustituir dos teclas y presenta un presupuesto. Después la directora deja que el responsable financiero revise el presupuesto antes de aceptarlo. Durante ese tiempo, las clases continúan en otra sala. Si el coste supera el presupuesto previsto, la escuela pedirá una segunda estimación antes de encargar la reparación.'},
questions:[{prompt:'چه کسی پیانو را بررسی می‌کند؟',choices:['معلم زبان','تکنسین','مسئول مالی'],correctIndex:1,explanation:'مدیر بررسی را به تکنسین واگذار می‌کند.',evidence:{fr:'examiner l’instrument par une technicienne',de:'von einer Technikerin untersuchen',es:'una técnica examine el instrumento'}},{prompt:'پیش از پذیرش برآورد چه کسی آن را می‌بیند؟',choices:['مسئول مالی','همهٔ دانش‌آموزان','راننده'],correctIndex:0,explanation:'مدیر اجازه می‌دهد مسئول مالی برآورد را بررسی کند.',evidence:{fr:'le responsable financier consulter le devis',de:'den Finanzverantwortlichen den Kostenvoranschlag prüfen',es:'el responsable financiero revise el presupuesto'}},{prompt:'اگر هزینه از بودجه بیشتر شود چه می‌کنند؟',choices:['کلاس‌ها را برای همیشه لغو می‌کنند','فوراً هزینه را می‌پردازند','برآورد دیگری می‌خواهند'],correctIndex:2,explanation:'در این صورت پیش از سفارش تعمیر برآورد دوم می‌خواهند.',evidence:{fr:'demandera une deuxième estimation',de:'holt die Schule eine zweite Schätzung ein',es:'pedirá una segunda estimación'}}],
notes:{fr:{explanation:'faire + infinitif می‌تواند ترتیب‌دادن انجام کار توسط دیگری و laisser + infinitif اجازه‌دادن را نشان دهد. مسئول ترتیب دادن با فرد انجام‌دهنده یکسان نیست.',first:'Elle fait examiner le piano par une technicienne.',second:'Elle laisse le responsable consulter le devis.',difference:'اولی ترتیب دادن بررسی و دومی اجازهٔ بررسی است.',phrases:[{text:'faire examiner',meaning:'ترتیب بررسی را دادن'},{text:'un devis',meaning:'برآورد هزینه'},{text:'dépasser le budget',meaning:'از بودجه فراتر رفتن'}]},de:{explanation:'lassen + Infinitiv بسته به بافت می‌تواند واگذار کردن یا اجازه دادن باشد. مشخص کنید چه کسی کار را ترتیب می‌دهد و چه کسی آن را انجام می‌دهد.',first:'Sie lässt das Klavier von einer Technikerin untersuchen.',second:'Sie lässt den Finanzverantwortlichen den Kostenvoranschlag prüfen.',difference:'اولی واگذاری بررسی و دومی اجازه یا ترتیب بررسی توسط مسئول مالی را بیان می‌کند.',phrases:[{text:'untersuchen lassen',meaning:'بررسی را به دیگری سپردن'},{text:'ein Kostenvoranschlag',meaning:'برآورد هزینه'},{text:'das Budget überschreiten',meaning:'از بودجه فراتر رفتن'}]},es:{explanation:'hacer que + subjuntivo می‌تواند سبب شدن و dejar que + subjuntivo اجازه دادن را بیان کند. فاعل هر کار را روشن نگه دارید.',first:'Hace que una técnica examine el piano.',second:'Deja que el responsable revise el presupuesto.',difference:'اولی ترتیب دادن بررسی و دومی اجازهٔ بررسی را نشان می‌دهد.',phrases:[{text:'encargar una reparación',meaning:'سفارش تعمیر'},{text:'un presupuesto',meaning:'برآورد هزینه'},{text:'superar el presupuesto',meaning:'از بودجه فراتر رفتن'}]}},
speaking:'برای همکارتان توضیح دهید چه کسی بررسی و تعمیر را ترتیب می‌دهد، چه کسی انجام می‌دهد و چه کسی هزینه را بررسی می‌کند.',writing:'پیام هماهنگی برای تعمیر یک وسیله بنویسید و نقش افراد، برآورد و شرط اقدام بعدی را توضیح دهید.',steps:['مشکل وسیله و مسئول را معرفی کنید.','کار واگذارشده و انجام‌دهنده را روشن کنید.','بازبینی هزینه را توضیح دهید.','شرط درخواست برآورد دوم را بنویسید.'],model:{fr:'Le piano ne fonctionne plus correctement. La directrice fait examiner l’instrument par une technicienne, qui prépare un devis. Elle laisse ensuite le responsable financier consulter ce devis avant de prendre une décision. Si le prix dépasse le budget, nous demanderons une deuxième estimation. En attendant, les cours auront lieu dans une autre salle.',de:'Das Klavier funktioniert nicht richtig. Die Leiterin lässt es von einer Technikerin untersuchen, die einen Kostenvoranschlag erstellt. Danach lässt sie den Finanzverantwortlichen den Voranschlag prüfen. Falls der Preis das Budget überschreitet, holen wir eine zweite Schätzung ein. Bis zur Entscheidung findet der Unterricht in einem anderen Raum statt.',es:'El piano no funciona bien. La directora hace que una técnica lo examine y prepare un presupuesto. Después deja que el responsable financiero revise la propuesta antes de tomar una decisión. Si el precio supera el presupuesto disponible, pediremos una segunda estimación. Mientras tanto, las clases tendrán lugar en otra sala.'}},
{id:'synthesis-sources',level:'b2',section:'foundation',number:21,title:'ترکیب اطلاعات دو منبع',passage:{
fr:'La ville envisage une piste cyclable près d’une école. Dans une enquête municipale, soixante familles disent que le trajet à vélo leur semblerait plus sûr avec une piste séparée. Le rapport précise que seules les familles ayant répondu ont été interrogées et qu’aucun accident n’a été mesuré pendant l’étude. De son côté, une association de commerçants craint que des places de stationnement disparaissent. Elle propose une phase d’essai avec un comptage des visiteurs et des livraisons. Les deux sources souhaitent une rue accessible, mais elles ne mesurent pas les mêmes effets. La ville doit encore publier le coût du projet avant de décider.',
de:'Die Stadt erwägt einen Radweg in der Nähe einer Schule. In einer städtischen Befragung sagen sechzig Familien, dass ihnen der Weg mit einem getrennten Radweg sicherer erschiene. Der Bericht weist darauf hin, dass nur antwortende Familien erfasst wurden und während der Studie keine Unfälle gemessen wurden. Ein Händlerverband befürchtet dagegen, dass Parkplätze wegfallen. Er schlägt eine Testphase mit einer Zählung von Besuchern und Lieferungen vor. Beide Quellen wünschen sich eine zugängliche Straße, messen aber nicht dieselben Auswirkungen. Die Stadt muss die Kosten des Projekts noch veröffentlichen, bevor sie entscheidet.',
es:'La ciudad estudia construir un carril bici cerca de una escuela. En una encuesta municipal, sesenta familias dicen que el trayecto en bicicleta les parecería más seguro con un carril separado. El informe aclara que solo se incluyó a las familias que respondieron y que no se midieron accidentes durante el estudio. Por su parte, una asociación de comerciantes teme que desaparezcan plazas de aparcamiento. Propone una fase de prueba con un recuento de visitantes y entregas. Las dos fuentes desean una calle accesible, pero no miden los mismos efectos. La ciudad todavía debe publicar el coste del proyecto antes de decidir.'},
questions:[{prompt:'نظر شصت خانواده دربارهٔ مسیر جدا چیست؟',choices:['فکر می‌کنند مسیر امن‌تر به نظر می‌رسد','تصمیم قطعی شهرداری را اعلام کرده‌اند','هزینهٔ پروژه را محاسبه کرده‌اند'],correctIndex:0,explanation:'خانواده‌های پاسخ‌دهنده احساس امنیت بیشتری را بیان کرده‌اند.',evidence:{fr:'soixante familles disent que le trajet à vélo leur semblerait plus sûr',de:'sechzig Familien, dass ihnen der Weg mit einem getrennten Radweg sicherer erschiene',es:'sesenta familias dicen que el trayecto en bicicleta les parecería más seguro'}},{prompt:'محدودیت گزارش شهرداری چیست؟',choices:['هیچ خانواده‌ای پاسخ نداده','فقط پاسخ‌دهندگان ثبت شده‌اند و تصادف‌ها سنجیده نشده‌اند','هزینهٔ پارکینگ اعلام شده است'],correctIndex:1,explanation:'نمونه محدود به پاسخ‌دهندگان است و تصادف اندازه‌گیری نشده است.',evidence:{fr:'seules les familles ayant répondu ont été interrogées et qu’aucun accident n’a été mesuré',de:'nur antwortende Familien erfasst wurden und während der Studie keine Unfälle gemessen wurden',es:'solo se incluyó a las familias que respondieron y que no se midieron accidentes'}},{prompt:'انجمن کسبه چه پیشنهادی می‌دهد؟',choices:['ساخت فوری بدون بررسی','لغو مدرسه','آزمایش همراه شمارش بازدیدها و تحویل‌ها'],correctIndex:2,explanation:'پیشنهاد انجمن یک مرحلهٔ آزمایشی با شمارش است.',evidence:{fr:'une phase d’essai avec un comptage des visiteurs et des livraisons',de:'eine Testphase mit einer Zählung von Besuchern und Lieferungen',es:'una fase de prueba con un recuento de visitantes y entregas'}}],
notes:{fr:{explanation:'برای ترکیب منابع از «selon» برای نسبت دادن، «tandis que» برای مقایسه و از عبارت محدودیت برای تفکیک نظر از شاهد استفاده کنید.',first:'Selon l’enquête, les familles répondantes se sentiraient plus en sécurité.',second:'Les commerçants craignent la perte de places de stationnement.',difference:'اولی برداشت گروه پاسخ‌دهنده و دومی نگرانی گروه دیگر است؛ هیچ‌کدام میزان واقعی تصادف را ثابت نمی‌کند.',phrases:[{text:'selon l’enquête',meaning:'طبق نظرسنجی'},{text:'une phase d’essai',meaning:'مرحلهٔ آزمایشی'},{text:'les données disponibles',meaning:'داده‌های موجود'}]},de:{explanation:'با «laut» یا «dem Bericht zufolge» داده را به منبع نسبت دهید؛ هنگام خلاصه‌سازی نگرانی را به‌عنوان واقعیت قطعی گزارش نکنید.',first:'Laut der Befragung erschiene den antwortenden Familien der Weg sicherer.',second:'Der Händlerverband befürchtet den Verlust von Parkplätzen.',difference:'اولی برداشت پاسخ‌دهندگان و دومی نگرانی گروه دیگر است، نه آمار واقعی تصادف.',phrases:[{text:'laut der Befragung',meaning:'طبق نظرسنجی'},{text:'eine Testphase',meaning:'مرحلهٔ آزمایشی'},{text:'verfügbare Daten',meaning:'داده‌های موجود'}]},es:{explanation:'«según» منبع را مشخص می‌کند و «por su parte» دیدگاه منبع دیگر را می‌آورد. برداشت یا ترس را به‌عنوان نتیجهٔ اثبات‌شده معرفی نکنید.',first:'Según la encuesta, el trayecto parecería más seguro a las familias que respondieron.',second:'Los comerciantes temen perder plazas de aparcamiento.',difference:'اولی برداشت پاسخ‌دهندگان و دومی نگرانی گروه دیگر است؛ آمار واقعی تصادف نیست.',phrases:[{text:'según la encuesta',meaning:'طبق نظرسنجی'},{text:'una fase de prueba',meaning:'مرحلهٔ آزمایشی'},{text:'los datos disponibles',meaning:'داده‌های موجود'}]}},
speaking:'دو منبع را برای فردی که آنها را ندیده خلاصه کنید: اشتراک، تفاوت، محدودیت و اطلاعات نامعلوم را بگویید.',writing:'ترکیبی بی‌طرفانه از دو منبع بنویسید و مشخص کنید برای تصمیم‌گیری چه دادهٔ دیگری لازم است.',steps:['هر منبع را نام ببرید.','نتیجه یا نگرانی را به منبع درست نسبت دهید.','محدودیت نمونه و موضوع مشترک را روشن کنید.','اطلاعات نامعلوم را جداگانه ذکر کنید.'],model:{fr:'Selon l’enquête municipale, les familles répondantes jugeraient le trajet à vélo plus sûr avec une piste séparée. L’étude ne mesure cependant pas les accidents et ne représente que les personnes ayant répondu. L’association de commerçants craint la perte de stationnement et propose un essai. Les deux sources souhaitent une rue accessible, mais évaluent des effets différents. Le coût reste à publier.',de:'Laut der städtischen Befragung erschiene den antwortenden Familien der Radweg sicherer. Die Studie misst jedoch keine Unfälle und erfasst nur die Familien, die geantwortet haben. Der Händlerverband befürchtet den Verlust von Parkplätzen und schlägt einen Test vor. Beide Quellen wünschen sich eine zugängliche Straße, betrachten aber unterschiedliche Auswirkungen. Die Kosten sind noch nicht veröffentlicht.',es:'Según la encuesta municipal, el recorrido parecería más seguro a las familias que respondieron. Sin embargo, el estudio no mide accidentes y solo incluye a quienes contestaron. La asociación de comerciantes teme perder aparcamiento y propone una prueba. Ambas fuentes buscan una calle accesible, pero consideran efectos diferentes. La ciudad todavía no ha publicado el coste.'}},
{id:'compare-locations',level:'b1',section:'foundation',number:13,title:'مقایسهٔ دو مکان برای کلاس',passage:{
fr:'Une association cherche une salle pour un cours du soir. La salle du centre coûte quarante euros et elle est plus proche de la gare que la salle du musée. Elle est aussi plus petite : elle accueille quinze personnes, contre vingt-cinq au musée. La salle du musée coûte cinquante euros, mais elle dispose d’un ascenseur. Au centre, il faut monter un escalier. Nadia pense que l’accessibilité est plus importante que le prix. Elle propose de demander si une salle accessible existe au centre avant de choisir. L’équipe devra aussi vérifier le nombre de participants inscrits.',
de:'Ein Verein sucht einen Raum für einen Abendkurs. Der Raum im Zentrum kostet vierzig Euro und liegt näher am Bahnhof als der Raum im Museum. Er ist auch kleiner: Dort passen fünfzehn Personen hinein, im Museum dagegen fünfundzwanzig. Der Raum im Museum kostet fünfzig Euro, hat aber einen Aufzug. Im Zentrum muss man eine Treppe hinaufgehen. Nadia findet die Barrierefreiheit wichtiger als den Preis. Sie schlägt vor, vor der Entscheidung zu fragen, ob es im Zentrum einen barrierefreien Raum gibt. Das Team muss auch die Zahl der angemeldeten Personen prüfen.',
es:'Una asociación busca una sala para un curso nocturno. La sala del centro cuesta cuarenta euros y está más cerca de la estación que la del museo. También es más pequeña: caben quince personas, frente a veinticinco en el museo. La sala del museo cuesta cincuenta euros, pero tiene ascensor. En el centro hay que subir una escalera. Nadia considera que la accesibilidad es más importante que el precio. Propone preguntar si hay una sala accesible en el centro antes de elegir. El equipo también debe comprobar el número de personas inscritas.'},
questions:[{prompt:'کدام محل به ایستگاه نزدیک‌تر است؟',choices:['مرکز','موزه','متن مشخص نمی‌کند'],correctIndex:0,explanation:'مرکز به ایستگاه نزدیک‌تر است.',evidence:{fr:'plus proche de la gare que la salle du musée',de:'näher am Bahnhof als der Raum im Museum',es:'más cerca de la estación que la del museo'}},{prompt:'کدام محل آسانسور دارد؟',choices:['مرکز','موزه','هیچ‌کدام'],correctIndex:1,explanation:'سالن موزه آسانسور دارد.',evidence:{fr:'elle dispose d’un ascenseur',de:'hat aber einen Aufzug',es:'pero tiene ascensor'}},{prompt:'پیش از انتخاب چه چیزی باید بررسی شود؟',choices:['زمان پرواز','رنگ کتاب‌ها','دسترسی سالن مرکز و تعداد ثبت‌نام‌ها'],correctIndex:2,explanation:'نادیا پیشنهاد می‌کند دسترسی و تعداد شرکت‌کنندگان بررسی شود.',evidence:{fr:'demander si une salle accessible existe au centre',de:'fragen, ob es im Zentrum einen barrierefreien Raum gibt',es:'preguntar si hay una sala accesible en el centro'}}],
notes:{fr:{explanation:'برای مقایسهٔ صفت از plus … que و برای برتری نسبی از le/la plus استفاده می‌شود؛ در جمله مشخص کنید کدام ویژگی مقایسه می‌شود.',first:'La salle du centre est plus petite que celle du musée.',second:'L’accessibilité est plus importante que le prix.',difference:'اولی اندازهٔ دو سالن و دومی اهمیت دو معیار را مقایسه می‌کند.',phrases:[{text:'près de la gare',meaning:'نزدیک ایستگاه'},{text:'une salle accessible',meaning:'سالن دسترس‌پذیر'},{text:'le nombre de participants',meaning:'تعداد شرکت‌کنندگان'}]},de:{explanation:'صفت مقایسه‌ای معمولاً با -er و als می‌آید. گاهی صفت تغییر آوایی دارد؛ näher و größer را مانند واژگان جداگانه تمرین کنید.',first:'Der Raum im Zentrum ist kleiner als der im Museum.',second:'Die Barrierefreiheit ist wichtiger als der Preis.',difference:'اولی اندازهٔ سالن‌ها و دومی اهمیت دو معیار را مقایسه می‌کند.',phrases:[{text:'in der Nähe des Bahnhofs',meaning:'نزدیک ایستگاه'},{text:'ein barrierefreier Raum',meaning:'سالن دسترس‌پذیر'},{text:'die Zahl der Teilnehmenden',meaning:'تعداد شرکت‌کنندگان'}]},es:{explanation:'مقایسهٔ صفت معمولاً با más … que و برتری نسبی با el/la más ساخته می‌شود؛ به تطابق صفت با اسم توجه کنید.',first:'La sala del centro es más pequeña que la del museo.',second:'La accesibilidad es más importante que el precio.',difference:'اولی اندازهٔ سالن‌ها و دومی اهمیت دو معیار را مقایسه می‌کند.',phrases:[{text:'cerca de la estación',meaning:'نزدیک ایستگاه'},{text:'una sala accesible',meaning:'سالن دسترس‌پذیر'},{text:'el número de participantes',meaning:'تعداد شرکت‌کنندگان'}]}},
speaking:'دو محل کلاس را از نظر قیمت، دسترسی و ظرفیت مقایسه کنید و انتخابتان را با دلیل توضیح دهید.',writing:'به گروه پیام بدهید و دو گزینه، یک مزیت و محدودیت هرکدام و سؤال باقی‌مانده را توضیح دهید.',steps:['دو گزینه را معرفی کنید.','قیمت، ظرفیت و دسترسی را مقایسه کنید.','یک دلیل برای ترجیح خود بیاورید.','اطلاعاتی را که باید بررسی شود ذکر کنید.'],model:{fr:'La salle du centre est moins chère et plus proche de la gare, mais elle est plus petite et il faut monter un escalier. La salle du musée coûte davantage, mais elle dispose d’un ascenseur. Avant de choisir, demandons s’il existe une salle accessible au centre et vérifions le nombre de participants.',de:'Der Raum im Zentrum ist günstiger und näher am Bahnhof, aber er ist kleiner und man muss eine Treppe benutzen. Der Raum im Museum kostet mehr, hat aber einen Aufzug. Vor der Entscheidung sollten wir fragen, ob es im Zentrum einen barrierefreien Raum gibt, und die Zahl der Teilnehmenden prüfen.',es:'La sala del centro es más barata y está más cerca de la estación, pero es más pequeña y hay que subir escaleras. La del museo cuesta más, pero tiene ascensor. Antes de elegir, preguntemos si hay una sala accesible en el centro y comprobemos el número de participantes.'}},
{id:'rules-and-advice',level:'b1',section:'foundation',number:14,title:'الزام، اجازه و توصیه در کارگاه',passage:{
fr:'Le samedi, un centre organise un atelier de cuisine pour douze personnes. Les participants doivent s’inscrire avant mercredi, car le nombre de places est limité. Ils doivent aussi informer l’équipe de leurs allergies avant l’atelier. Ils peuvent apporter leur propre tablier, mais ce n’est pas obligatoire : le centre en fournit. La responsable conseille de porter des chaussures fermées. Il ne faut pas entrer dans la cuisine avant l’arrivée du formateur. Après l’activité, chacun aide à nettoyer son espace. En cas de question, les participants peuvent appeler le centre pendant les heures d’ouverture.',
de:'Am Samstag organisiert ein Zentrum einen Kochkurs für zwölf Personen. Die Teilnehmenden müssen sich bis Mittwoch anmelden, weil die Plätze begrenzt sind. Sie müssen das Team vor dem Kurs auch über Allergien informieren. Sie dürfen eine eigene Schürze mitbringen, aber das ist nicht verpflichtend: Das Zentrum stellt welche bereit. Die Leiterin empfiehlt, geschlossene Schuhe zu tragen. Vor der Ankunft des Kursleiters darf niemand die Küche betreten. Nach dem Kurs hilft jede Person beim Reinigen ihres Arbeitsplatzes. Bei Fragen können die Teilnehmenden das Zentrum während der Öffnungszeiten anrufen.',
es:'El sábado, un centro organiza un taller de cocina para doce personas. Los participantes tienen que inscribirse antes del miércoles porque las plazas son limitadas. También deben informar al equipo de sus alergias antes del taller. Pueden llevar su propio delantal, pero no es obligatorio: el centro proporciona delantales. La responsable aconseja llevar zapatos cerrados. No se debe entrar en la cocina antes de que llegue el formador. Después de la actividad, cada persona ayuda a limpiar su espacio. Si tienen preguntas, los participantes pueden llamar al centro durante el horario de apertura.'},
questions:[{prompt:'ثبت‌نام تا چه زمانی لازم است؟',choices:['تا چهارشنبه','تا شنبه بعد','بعد از کارگاه'],correctIndex:0,explanation:'ثبت‌نام باید پیش از چهارشنبه انجام شود.',evidence:{fr:'s’inscrire avant mercredi',de:'sich bis Mittwoch anmelden',es:'inscribirse antes del miércoles'}},{prompt:'آیا آوردن پیش‌بند شخصی اجباری است؟',choices:['بله برای همه','خیر، مرکز پیش‌بند فراهم می‌کند','فقط برای مدرس'],correctIndex:1,explanation:'آوردن پیش‌بند شخصی مجاز است اما اجباری نیست.',evidence:{fr:'ce n’est pas obligatoire : le centre en fournit',de:'das ist nicht verpflichtend: Das Zentrum stellt welche bereit',es:'no es obligatorio: el centro proporciona delantales'}},{prompt:'پیش از رسیدن مدرس چه قانونی وجود دارد؟',choices:['باید غذا را شروع کنند','باید مرکز را ترک کنند','نباید وارد آشپزخانه شوند'],correctIndex:2,explanation:'ورود پیش از رسیدن مدرس مجاز نیست.',evidence:{fr:'ne faut pas entrer dans la cuisine avant l’arrivée du formateur',de:'Vor der Ankunft des Kursleiters darf niemand die Küche betreten',es:'No se debe entrar en la cocina antes de que llegue el formador'}}],
notes:{fr:{explanation:'devoir الزام، pouvoir اجازه یا امکان و conseiller توصیه را بیان می‌کند. «il ne faut pas» در این متن ممنوعیت است؛ توصیه و الزام را یکی نگیرید.',first:'Vous devez vous inscrire avant mercredi.',second:'Vous pouvez apporter votre tablier.',difference:'اولی الزام ثبت‌نام و دومی اجازهٔ اختیاری است.',phrases:[{text:'les places sont limitées',meaning:'ظرفیت محدود است'},{text:'informer de ses allergies',meaning:'اطلاع دادن دربارهٔ حساسیت‌ها'},{text:'porter des chaussures fermées',meaning:'پوشیدن کفش بسته'}]},de:{explanation:'müssen الزام، dürfen اجازه و empfehlen توصیه را بیان می‌کند. «nicht dürfen» ممنوعیت است، در حالی که «nicht müssen» یعنی ضرورتی ندارد.',first:'Sie müssen sich bis Mittwoch anmelden.',second:'Sie dürfen eine eigene Schürze mitbringen.',difference:'اولی الزام و دومی اجازهٔ اختیاری است.',phrases:[{text:'begrenzte Plätze',meaning:'ظرفیت محدود'},{text:'über Allergien informieren',meaning:'اطلاع دادن دربارهٔ حساسیت‌ها'},{text:'geschlossene Schuhe tragen',meaning:'پوشیدن کفش بسته'}]},es:{explanation:'tener que الزام، poder اجازه یا امکان و aconsejar توصیه را نشان می‌دهد. در این متن «no se debe» ممنوعیت را بیان می‌کند.',first:'Tienen que inscribirse antes del miércoles.',second:'Pueden llevar su propio delantal.',difference:'اولی الزام ثبت‌نام و دومی اجازهٔ اختیاری است.',phrases:[{text:'plazas limitadas',meaning:'ظرفیت محدود'},{text:'informar de las alergias',meaning:'اطلاع دادن دربارهٔ حساسیت‌ها'},{text:'llevar zapatos cerrados',meaning:'پوشیدن کفش بسته'}]}},
speaking:'قواعد کارگاه را برای دوستتان توضیح دهید و الزام، اجازه، توصیه و ممنوعیت را جدا کنید.',writing:'راهنمای کوتاهی برای شرکت‌کننده بنویسید و مهلت، اطلاعات لازم، وسایل اختیاری و قانون ورود را مشخص کنید.',steps:['زمان و مهلت ثبت‌نام را بنویسید.','دو الزام را مشخص کنید.','اجازه و توصیه را از الزام جدا کنید.','قانون ورود و راه پرسیدن سؤال را اضافه کنید.'],model:{fr:'Pour participer à l’atelier, vous devez vous inscrire avant mercredi et informer l’équipe de vos allergies. Vous pouvez apporter votre tablier, mais le centre en fournit aussi. La responsable conseille de porter des chaussures fermées. Il ne faut pas entrer dans la cuisine avant l’arrivée du formateur. Pour toute question, appelez le centre pendant ses heures d’ouverture.',de:'Für den Kochkurs müssen Sie sich bis Mittwoch anmelden und das Team über Allergien informieren. Sie dürfen eine eigene Schürze mitbringen, aber das Zentrum stellt auch Schürzen bereit. Die Leiterin empfiehlt geschlossene Schuhe. Vor der Ankunft des Kursleiters dürfen Sie die Küche nicht betreten. Bei Fragen rufen Sie das Zentrum während der Öffnungszeiten an.',es:'Para participar en el taller, tienen que inscribirse antes del miércoles e informar al equipo de sus alergias. Pueden llevar su delantal, pero el centro también proporciona uno. La responsable aconseja llevar zapatos cerrados. No deben entrar en la cocina antes de que llegue el formador. Si tienen preguntas, llamen al centro durante el horario de apertura.'}},
{id:'job-interview',level:'b1',section:'survival',number:8,title:'مصاحبه برای کار در کتابخانه',passage:{
fr:'Lors d’un entretien pour un poste à la bibliothèque, Karim présente son expérience. Il a travaillé pendant deux ans dans une petite librairie, où il aidait les clients à trouver des livres et organisait les commandes. Il explique qu’il aime travailler en équipe et qu’il apprend rapidement à utiliser de nouveaux logiciels. La responsable lui demande s’il peut travailler le samedi. Karim répond qu’il est disponible deux samedis par mois, mais qu’il suit un cours les autres samedis. Avant la fin de l’entretien, il demande quelle formation est prévue pour les nouveaux employés et quand la décision sera communiquée.',
de:'Bei einem Vorstellungsgespräch für eine Stelle in der Bibliothek stellt Karim seine Erfahrung vor. Er hat zwei Jahre in einer kleinen Buchhandlung gearbeitet. Dort half er Kundinnen und Kunden bei der Suche nach Büchern und organisierte Bestellungen. Er erklärt, dass er gern im Team arbeitet und schnell lernt, neue Programme zu benutzen. Die Leiterin fragt ihn, ob er samstags arbeiten kann. Karim antwortet, dass er an zwei Samstagen im Monat Zeit hat, an den anderen aber einen Kurs besucht. Vor dem Ende des Gesprächs fragt er nach der Einarbeitung für neue Mitarbeitende und danach, wann die Entscheidung mitgeteilt wird.',
es:'Durante una entrevista para un puesto en una biblioteca, Karim presenta su experiencia. Trabajó dos años en una pequeña librería, donde ayudaba a los clientes a encontrar libros y organizaba pedidos. Explica que le gusta trabajar en equipo y que aprende rápido a usar nuevos programas. La responsable le pregunta si puede trabajar los sábados. Karim responde que está disponible dos sábados al mes, pero que los otros sábados asiste a un curso. Antes de terminar la entrevista, pregunta qué formación recibirán los nuevos empleados y cuándo se comunicará la decisión.'},
questions:[{prompt:'تجربهٔ قبلی کریم کجاست؟',choices:['دو سال در کتاب‌فروشی','یک سال در بیمارستان','پنج سال در مدرسه'],correctIndex:0,explanation:'او دو سال در کتاب‌فروشی کار کرده است.',evidence:{fr:'pendant deux ans dans une petite librairie',de:'zwei Jahre in einer kleinen Buchhandlung gearbeitet',es:'Trabajó dos años en una pequeña librería'}},{prompt:'او چند شنبه در ماه وقت دارد؟',choices:['همهٔ شنبه‌ها','دو شنبه','هیچ شنبه‌ای'],correctIndex:1,explanation:'او دو شنبه در ماه در دسترس است.',evidence:{fr:'disponible deux samedis par mois',de:'an zwei Samstagen im Monat Zeit hat',es:'disponible dos sábados al mes'}},{prompt:'در پایان مصاحبه چه می‌پرسد؟',choices:['قیمت کتاب‌ها','زمان ناهار امروز','آموزش کارکنان تازه و زمان تصمیم'],correctIndex:2,explanation:'او دربارهٔ آموزش و زمان اعلام تصمیم می‌پرسد.',evidence:{fr:'quelle formation est prévue pour les nouveaux employés',de:'nach der Einarbeitung für neue Mitarbeitende',es:'qué formación recibirán los nuevos empleados'}}],
notes:{fr:{explanation:'در معرفی تجربه از فعل گذشته برای کار انجام‌شده و حال برای مهارت کنونی استفاده کنید. محدودیت زمان را صادقانه و همراه گزینهٔ موجود بیان کنید.',first:'J’ai travaillé deux ans dans une librairie.',second:'Je suis disponible deux samedis par mois.',difference:'اولی تجربهٔ گذشته و دومی دسترسی فعلی است.',phrases:[{text:'travailler en équipe',meaning:'کار گروهی'},{text:'être disponible',meaning:'در دسترس بودن'},{text:'la formation des nouveaux employés',meaning:'آموزش کارکنان تازه'}]},de:{explanation:'برای تجربهٔ قبلی Perfekt و برای دسترسی فعلی Präsens به کار ببرید. درخواست توضیح دربارهٔ Einarbeitung گفت‌وگو را ادامه می‌دهد.',first:'Ich habe zwei Jahre in einer Buchhandlung gearbeitet.',second:'Ich habe an zwei Samstagen im Monat Zeit.',difference:'اولی تجربهٔ گذشته و دومی دسترسی فعلی است.',phrases:[{text:'im Team arbeiten',meaning:'کار گروهی'},{text:'Zeit haben',meaning:'در دسترس بودن'},{text:'die Einarbeitung',meaning:'آموزش آغاز کار'}]},es:{explanation:'برای تجربهٔ پایان‌یافتهٔ شغلی از زمان گذشتهٔ مناسب و برای دسترسی فعلی از حال استفاده کنید؛ محدودیت خود را روشن بیان کنید.',first:'Trabajé dos años en una librería.',second:'Estoy disponible dos sábados al mes.',difference:'اولی تجربهٔ گذشته و دومی دسترسی فعلی است.',phrases:[{text:'trabajar en equipo',meaning:'کار گروهی'},{text:'estar disponible',meaning:'در دسترس بودن'},{text:'la formación inicial',meaning:'آموزش آغاز کار'}]}},
speaking:'برای مصاحبه‌ای فرضی خود را معرفی کنید، یک وظیفهٔ قبلی و زمان‌های در دسترس را بیان و یک پرسش دربارهٔ آموزش مطرح کنید.',writing:'معرفی کوتاهی برای مصاحبه بنویسید که تجربه، مهارت، زمان در دسترس و یک پرسش را دربر گیرد.',steps:['شغل مورد نظر را معرفی کنید.','تجربه و یک وظیفهٔ مشخص را بنویسید.','یک مهارت و زمان در دسترس را اضافه کنید.','پرسشی دربارهٔ آموزش یا گام بعدی بنویسید.'],model:{fr:'Bonjour, je souhaite travailler dans votre bibliothèque. J’ai travaillé deux ans dans une librairie et j’aidais les clients à trouver des livres. J’aime travailler en équipe et je peux apprendre à utiliser de nouveaux logiciels. Je suis disponible deux samedis par mois. Pourriez-vous me dire quelle formation est prévue pour les nouveaux employés ?',de:'Guten Tag, ich möchte gern in Ihrer Bibliothek arbeiten. Ich habe zwei Jahre in einer Buchhandlung gearbeitet und Kunden bei der Suche nach Büchern geholfen. Ich arbeite gern im Team und lerne neue Programme schnell. An zwei Samstagen im Monat habe ich Zeit. Können Sie mir sagen, wie die Einarbeitung für neue Mitarbeitende aussieht?',es:'Buenos días, me gustaría trabajar en su biblioteca. Trabajé dos años en una librería y ayudaba a los clientes a encontrar libros. Me gusta trabajar en equipo y aprendo rápido a usar programas nuevos. Estoy disponible dos sábados al mes. ¿Podrían decirme qué formación recibirán los nuevos empleados?'}},
{id:'digital-tool',level:'b1',section:'survival',number:16,title:'استفاده از ابزار برنامه‌ریزی',passage:{
fr:'Une équipe de bénévoles organise les tâches avec une application partagée. Chaque personne peut voir les dates et ajouter un commentaire. Selon Inès, cet outil réduit le nombre de messages et permet de trouver rapidement les informations. Cependant, son collègue Louis signale que certains bénévoles ne consultent pas l’application tous les jours. Il propose donc d’envoyer aussi un résumé par courriel chaque vendredi. Avant de choisir définitivement, l’équipe veut essayer cette méthode pendant un mois. Elle demandera ensuite aux bénévoles si les informations étaient claires et si le nouveau système leur a fait gagner du temps.',
de:'Ein Team von Freiwilligen organisiert seine Aufgaben mit einer gemeinsamen App. Jede Person kann Termine sehen und einen Kommentar hinzufügen. Laut Ines verringert das Werkzeug die Zahl der Nachrichten und hilft dabei, Informationen schnell zu finden. Ihr Kollege Louis weist jedoch darauf hin, dass einige Freiwillige die App nicht täglich öffnen. Deshalb schlägt er vor, jeden Freitag zusätzlich eine Zusammenfassung per E-Mail zu senden. Bevor das Team endgültig entscheidet, möchte es diese Methode einen Monat lang testen. Danach fragt es die Freiwilligen, ob die Informationen klar waren und ob das neue System ihnen Zeit gespart hat.',
es:'Un equipo de voluntarios organiza sus tareas con una aplicación compartida. Cada persona puede ver las fechas y añadir un comentario. Según Inés, esta herramienta reduce el número de mensajes y permite encontrar información rápidamente. Sin embargo, su compañero Luis señala que algunos voluntarios no consultan la aplicación todos los días. Por eso propone enviar también un resumen por correo electrónico cada viernes. Antes de decidir definitivamente, el equipo quiere probar este método durante un mes. Después preguntará a los voluntarios si la información era clara y si el nuevo sistema les ahorró tiempo.'},
questions:[{prompt:'هر عضو در برنامه چه کاری می‌تواند انجام دهد؟',choices:['تاریخ‌ها را ببیند و نظر اضافه کند','پرداخت بانکی انجام دهد','کلاس را حذف کند'],correctIndex:0,explanation:'اعضا می‌توانند تاریخ‌ها را ببینند و نظر بنویسند.',evidence:{fr:'voir les dates et ajouter un commentaire',de:'Termine sehen und einen Kommentar hinzufügen',es:'ver las fechas y añadir un comentario'}},{prompt:'محدودیت مطرح‌شده توسط لوئی چیست؟',choices:['برنامه هیچ تاریخی ندارد','بعضی داوطلبان هر روز برنامه را بررسی نمی‌کنند','همهٔ داوطلبان ایمیل ندارند'],correctIndex:1,explanation:'بعضی افراد هر روز به برنامه سر نمی‌زنند.',evidence:{fr:'certains bénévoles ne consultent pas l’application tous les jours',de:'einige Freiwillige die App nicht täglich öffnen',es:'algunos voluntarios no consultan la aplicación todos los días'}},{prompt:'تیم چگونه روش را ارزیابی می‌کند؟',choices:['بدون آزمایش آن را دائمی می‌کند','فقط هزینهٔ رایانه را بررسی می‌کند','یک ماه آزمایش و سپس از داوطلبان پرسش می‌کند'],correctIndex:2,explanation:'پس از یک ماه آزمایش بازخورد داوطلبان را می‌گیرد.',evidence:{fr:'essayer cette méthode pendant un mois',de:'diese Methode einen Monat lang testen',es:'probar este método durante un mes'}}],
notes:{fr:{explanation:'«selon» نظر را به منبع نسبت می‌دهد؛ «cependant» محدودیت را مطرح و «donc» راهکار را به مشکل وصل می‌کند.',first:'Selon Inès, l’application réduit les messages.',second:'Cependant, certains bénévoles ne la consultent pas chaque jour.',difference:'اولی مزیت بیان‌شده و دومی محدودیت استفاده است.',phrases:[{text:'une application partagée',meaning:'برنامهٔ مشترک'},{text:'ajouter un commentaire',meaning:'افزودن نظر'},{text:'gagner du temps',meaning:'صرفه‌جویی در وقت'}]},de:{explanation:'«laut» نظر را به منبع نسبت می‌دهد؛ «jedoch» تضاد و «deshalb» نتیجه را بیان می‌کند. بعد از deshalb فعل در جایگاه دوم می‌آید.',first:'Laut Ines reduziert die App die Zahl der Nachrichten.',second:'Einige Freiwillige öffnen sie jedoch nicht täglich.',difference:'اولی مزیت بیان‌شده و دومی محدودیت استفاده است.',phrases:[{text:'eine gemeinsame App',meaning:'برنامهٔ مشترک'},{text:'einen Kommentar hinzufügen',meaning:'افزودن نظر'},{text:'Zeit sparen',meaning:'صرفه‌جویی در وقت'}]},es:{explanation:'«según» نظر را به منبع نسبت می‌دهد؛ «sin embargo» محدودیت و «por eso» نتیجه را بیان می‌کند.',first:'Según Inés, la aplicación reduce los mensajes.',second:'Sin embargo, algunos voluntarios no la consultan cada día.',difference:'اولی مزیت بیان‌شده و دومی محدودیت استفاده است.',phrases:[{text:'una aplicación compartida',meaning:'برنامهٔ مشترک'},{text:'añadir un comentario',meaning:'افزودن نظر'},{text:'ahorrar tiempo',meaning:'صرفه‌جویی در وقت'}]}},
speaking:'یک ابزار دیجیتال را معرفی کنید، یک مزیت و یک محدودیت آن را با مثال بگویید و راهی برای آزمودن آن پیشنهاد کنید.',writing:'برای گروه دربارهٔ استفادهٔ آزمایشی از یک ابزار پیام بنویسید؛ مزیت، محدودیت، مدت آزمایش و شیوهٔ دریافت بازخورد را بیان کنید.',steps:['ابزار و کاربرد را معرفی کنید.','یک مزیت و یک محدودیت بیاورید.','یک راه‌حل و مدت آزمایش پیشنهاد کنید.','نحوهٔ جمع‌آوری بازخورد را روشن کنید.'],model:{fr:'Nous pourrions utiliser une application partagée pour organiser nos tâches. Elle permet de voir les dates rapidement, mais certaines personnes ne la consultent pas chaque jour. Je propose donc un résumé par courriel chaque vendredi. Essayons cette méthode pendant un mois, puis demandons au groupe si les informations étaient claires.',de:'Wir könnten eine gemeinsame App für unsere Aufgaben nutzen. Dort kann man Termine schnell sehen, aber einige Personen öffnen sie nicht jeden Tag. Deshalb schlage ich eine Zusammenfassung per E-Mail jeden Freitag vor. Wir sollten diese Methode einen Monat lang testen und danach das Team fragen, ob die Informationen klar waren.',es:'Podríamos utilizar una aplicación compartida para organizar las tareas. Permite ver las fechas rápidamente, pero algunas personas no la consultan cada día. Por eso propongo enviar un resumen por correo cada viernes. Probemos este método durante un mes y después preguntemos al grupo si la información estaba clara.'}},
{id:'register-audience',level:'b2',section:'foundation',number:20,title:'انتخاب لحن با مخاطب',passage:{
fr:'Maya organise une rencontre et apprend que la salle prévue sera fermée mardi pour maintenance. Elle doit annoncer le changement à deux publics. À sa collègue qu’elle connaît bien, elle écrit : « Salut ! La salle sera fermée mardi. On peut se retrouver dans la bibliothèque à dix heures ? » Pour le responsable du bâtiment, elle prépare un courriel plus formel : « Bonjour Monsieur, en raison de la fermeture de la salle mardi, pourriez-vous nous confirmer si la bibliothèque est disponible à dix heures ? » Dans les deux messages, l’information et la question restent les mêmes ; seules les formules et le degré de familiarité changent. Maya attend la confirmation avant d’informer tout le groupe.',
de:'Maya organisiert ein Treffen und erfährt, dass der geplante Raum am Dienstag wegen Wartungsarbeiten geschlossen sein wird. Sie muss die Änderung zwei verschiedenen Personen mitteilen. Einer Kollegin, die sie gut kennt, schreibt sie: „Hallo! Der Raum ist am Dienstag geschlossen. Können wir uns um zehn in der Bibliothek treffen?“ Für den Gebäudeverantwortlichen formuliert sie eine förmlichere E-Mail: „Guten Tag, könnten Sie uns wegen der Schließung des Raums am Dienstag bitte bestätigen, ob die Bibliothek um zehn Uhr verfügbar ist?“ In beiden Nachrichten bleiben die Information und die Frage gleich; nur die Formulierungen und der Grad der Vertrautheit ändern sich. Maya wartet auf die Bestätigung, bevor sie die ganze Gruppe informiert.',
es:'Maya organiza una reunión y se entera de que la sala prevista estará cerrada el martes por mantenimiento. Tiene que comunicar el cambio a dos destinatarios. A una compañera que conoce bien le escribe: «¡Hola! La sala estará cerrada el martes. ¿Podemos reunirnos en la biblioteca a las diez?» Para el responsable del edificio prepara un correo más formal: «Buenos días: debido al cierre de la sala el martes, ¿podría confirmarnos si la biblioteca está disponible a las diez?» En ambos mensajes la información y la pregunta son las mismas; solo cambian las fórmulas y el grado de confianza. Maya espera la confirmación antes de informar a todo el grupo.'},
questions:[{prompt:'چرا محل برنامه عوض می‌شود؟',choices:['سالن سه‌شنبه برای نگهداری بسته است','کتابخانه برای همیشه بسته است','گروه زمان جلسه را فراموش کرده'],correctIndex:0,explanation:'سالن مورد نظر به علت نگهداری سه‌شنبه بسته خواهد بود.',evidence:{fr:'la salle prévue sera fermée mardi pour maintenance',de:'der geplante Raum am Dienstag wegen Wartungsarbeiten geschlossen sein wird',es:'la sala prevista estará cerrada el martes por mantenimiento'}},{prompt:'چه چیزی در هر دو پیام ثابت می‌ماند؟',choices:['فقط سلام دوستانه','اطلاعات و پرسش','نام همهٔ اعضا'],correctIndex:1,explanation:'اطلاعات و پرسش تغییر نمی‌کنند؛ لحن متفاوت است.',evidence:{fr:'l’information et la question restent les mêmes',de:'die Information und die Frage gleich',es:'la información y la pregunta son las mismas'}},{prompt:'مایا پیش از اطلاع دادن به گروه چه می‌کند؟',choices:['جلسه را لغو می‌کند','از همه پول می‌گیرد','منتظر تأیید می‌ماند'],correctIndex:2,explanation:'او ابتدا منتظر تأیید می‌ماند.',evidence:{fr:'attend la confirmation avant d’informer tout le groupe',de:'wartet auf die Bestätigung, bevor sie die ganze Gruppe informiert',es:'espera la confirmación antes de informar a todo el grupo'}}],
notes:{fr:{explanation:'با همکار نزدیک «tu/on» و سلام دوستانه ممکن است مناسب باشد؛ با مخاطب رسمی «vous» و درخواست با conditionnel مانند pourriez-vous لحن مؤدبانه‌تری دارد. رابطه و عرف محیط را در نظر بگیرید.',first:'On peut se retrouver à dix heures ?',second:'Pourriez-vous nous confirmer la disponibilité à dix heures ?',difference:'هر دو پرسش دربارهٔ جلسه‌اند، اما دومی برای مخاطب رسمی محتاطانه‌تر است.',phrases:[{text:'en raison de la fermeture',meaning:'به علت بسته شدن'},{text:'confirmer la disponibilité',meaning:'تأیید در دسترس بودن'},{text:'avant d’informer le groupe',meaning:'پیش از اطلاع به گروه'}]},de:{explanation:'با همکار نزدیک می‌توان du به کار برد؛ برای مخاطب رسمی Sie و عبارتی مانند «Könnten Sie bitte …?» مناسب‌تر است. اطلاعات را در هر دو نسخه یکسان نگه دارید.',first:'Können wir uns um zehn treffen?',second:'Könnten Sie bitte die Verfügbarkeit um zehn bestätigen?',difference:'اولی پرسشی مستقیم و دومی درخواستی رسمی‌تر است.',phrases:[{text:'wegen der Schließung',meaning:'به علت بسته شدن'},{text:'die Verfügbarkeit bestätigen',meaning:'تأیید در دسترس بودن'},{text:'die Gruppe informieren',meaning:'اطلاع دادن به گروه'}]},es:{explanation:'با مخاطب آشنا می‌توان از tú و با مخاطب رسمی از usted استفاده کرد؛ «¿podría…?» درخواست را مؤدبانه‌تر می‌کند. درجهٔ رسمیت به منطقه و رابطه نیز بستگی دارد.',first:'¿Podemos reunirnos a las diez?',second:'¿Podría confirmar si la sala está disponible a las diez?',difference:'اولی درخواست مستقیم و دومی برای مخاطب رسمی مؤدبانه‌تر است.',phrases:[{text:'debido al cierre',meaning:'به علت بسته شدن'},{text:'confirmar la disponibilidad',meaning:'تأیید در دسترس بودن'},{text:'informar al grupo',meaning:'اطلاع دادن به گروه'}]}},
speaking:'تعطیلی فرضی یک محل و درخواست جایگزین را یک بار برای همکار نزدیک و بار دیگر برای مسئول رسمی توضیح دهید.',writing:'دو پیام برای مخاطبان متفاوت بنویسید؛ اطلاعات ثابت بمانند، اما سلام، درخواست و پایان متناسب با مخاطب باشند.',steps:['واقعیت و درخواست مشترک را مشخص کنید.','نسخهٔ دوستانه را بنویسید.','نسخهٔ رسمی با درخواست مؤدبانه بنویسید.','ثبات زمان، محل و اطلاعات را بازبینی کنید.'],model:{fr:'Salut ! La salle est fermée mardi. Est-ce qu’on peut se retrouver à la bibliothèque à dix heures ?\n\nBonjour Monsieur, la salle prévue sera fermée mardi. Pourriez-vous nous confirmer si la bibliothèque est disponible à dix heures ? Nous informerons le groupe après votre réponse. Merci pour votre aide. Cordialement.',de:'Hallo! Der Raum ist am Dienstag geschlossen. Können wir uns um zehn in der Bibliothek treffen?\n\nGuten Tag, der geplante Raum ist am Dienstag geschlossen. Könnten Sie uns bitte bestätigen, ob die Bibliothek um zehn Uhr verfügbar ist? Nach Ihrer Antwort informieren wir die Gruppe. Vielen Dank und freundliche Grüße.',es:'¡Hola! La sala estará cerrada el martes. ¿Podemos reunirnos en la biblioteca a las diez?\n\nBuenos días: la sala prevista estará cerrada el martes. ¿Podría confirmarnos si la biblioteca está disponible a las diez? Informaremos al grupo después de recibir su respuesta. Muchas gracias. Un saludo.'}},
{id:'future-learning-plan',level:'b1',section:'foundation',number:5,title:'هدف و برنامهٔ آینده',passage:{
fr:'Dans six mois, Yara souhaite commencer une formation de guide touristique. Avant de s’inscrire, elle va vérifier les conditions et demander le prix du cours. Elle prévoit aussi de consacrer deux heures par semaine à l’étude de la langue. Sa collègue lui propose de s’entraîner avec elle le mardi soir. Si les horaires de la formation ne conviennent pas, Yara cherchera un autre cours. Elle sait que son plan peut changer selon son emploi du temps et son budget. À la fin du mois, elle comparera les réponses des écoles et prendra une décision.',
de:'In sechs Monaten möchte Yara eine Ausbildung zur Reiseführerin beginnen. Bevor sie sich anmeldet, will sie die Voraussetzungen prüfen und nach dem Preis fragen. Sie plant außerdem, jede Woche zwei Stunden für das Sprachlernen einzuplanen. Ihre Kollegin bietet an, am Dienstagabend mit ihr zu üben. Falls die Zeiten der Ausbildung nicht passen, sucht Yara einen anderen Kurs. Sie weiß, dass sich ihr Plan je nach Arbeitszeit und Budget ändern kann. Am Ende des Monats vergleicht sie die Antworten der Schulen und trifft eine Entscheidung.',
es:'Dentro de seis meses, Yara quiere empezar una formación para ser guía turística. Antes de inscribirse, va a comprobar los requisitos y preguntar el precio del curso. También piensa dedicar dos horas por semana al estudio del idioma. Su compañera le propone practicar con ella los martes por la tarde. Si el horario de la formación no le conviene, Yara buscará otro curso. Sabe que su plan puede cambiar según su horario de trabajo y su presupuesto. Al final del mes comparará las respuestas de las escuelas y tomará una decisión.'},
questions:[{prompt:'هدف یارا برای شش ماه آینده چیست؟',choices:['شروع آموزش راهنمای گردشگری','خرید کتابخانه','لغو کار'],correctIndex:0,explanation:'او می‌خواهد آموزش راهنمای گردشگری را آغاز کند.',evidence:{fr:'commencer une formation de guide touristique',de:'eine Ausbildung zur Reiseführerin beginnen',es:'empezar una formación para ser guía turística'}},{prompt:'هر هفته چقدر زمان برای مطالعهٔ زبان در نظر دارد؟',choices:['یک ساعت','دو ساعت','ده ساعت'],correctIndex:1,explanation:'او هفته‌ای دو ساعت در نظر دارد.',evidence:{fr:'deux heures par semaine à l’étude de la langue',de:'jede Woche zwei Stunden für das Sprachlernen',es:'dos horas por semana al estudio del idioma'}},{prompt:'پیش از تصمیم پایان ماه چه می‌کند؟',choices:['همهٔ دوره‌ها را لغو می‌کند','بدون بررسی ثبت‌نام می‌کند','پاسخ آموزشگاه‌ها را مقایسه می‌کند'],correctIndex:2,explanation:'او پاسخ‌ها را مقایسه و سپس تصمیم می‌گیرد.',evidence:{fr:'comparera les réponses des écoles et prendra une décision',de:'vergleicht sie die Antworten der Schulen und trifft eine Entscheidung',es:'comparará las respuestas de las escuelas y tomará una decisión'}}],
notes:{fr:{explanation:'aller + infinitif می‌تواند برنامهٔ نزدیک و futur simple اقدام آینده را بیان کند؛ برای بیان هدف از souhaiter + infinitif استفاده کنید.',first:'Je vais vérifier les conditions.',second:'Je prendrai une décision à la fin du mois.',difference:'اولی اقدام برنامه‌ریزی‌شده و دومی تصمیم آینده در زمان مشخص است.',phrases:[{text:'vérifier les conditions',meaning:'بررسی شرایط'},{text:'consacrer du temps à',meaning:'زمان اختصاص دادن به'},{text:'prendre une décision',meaning:'تصمیم گرفتن'}]},de:{explanation:'برای برنامهٔ آینده می‌توان از Präsens با زمان مشخص و فعل‌های möchte یا planen استفاده کرد؛ Futur I تنها راه بیان آینده نیست.',first:'Ich möchte in sechs Monaten eine Ausbildung beginnen.',second:'Am Monatsende vergleiche ich die Antworten.',difference:'اولی هدف و دومی اقدام برنامه‌ریزی‌شده است.',phrases:[{text:'Voraussetzungen prüfen',meaning:'بررسی شرایط'},{text:'Zeit einplanen',meaning:'زمان در نظر گرفتن'},{text:'eine Entscheidung treffen',meaning:'تصمیم گرفتن'}]},es:{explanation:'ir a + infinitivo می‌تواند برنامهٔ آینده و futuro simple اقدام آینده را بیان کند؛ querer + infinitivo هدف را معرفی می‌کند.',first:'Voy a comprobar los requisitos.',second:'Tomaré una decisión al final del mes.',difference:'اولی اقدام برنامه‌ریزی‌شده و دومی تصمیم در آینده است.',phrases:[{text:'comprobar los requisitos',meaning:'بررسی شرایط'},{text:'dedicar tiempo a',meaning:'زمان اختصاص دادن به'},{text:'tomar una decisión',meaning:'تصمیم گرفتن'}]}},
speaking:'هدفی برای شش ماه آینده، دو قدم عملی و یک برنامهٔ جایگزین را بیان کنید.',writing:'برای دوستی برنامه‌ای بنویسید؛ هدف، قدم‌ها، زمان تصمیم و شرایط تغییر را توضیح دهید.',steps:['هدف و زمان آن را مشخص کنید.','دو اقدام عملی بنویسید.','احتمال تغییر برنامه را بیان کنید.','زمان تصمیم را اضافه کنید.'],model:{fr:'Dans six mois, je souhaite commencer une formation. Avant de m’inscrire, je vais vérifier les conditions et le prix. Je consacrerai aussi deux heures par semaine à la langue et je pratiquerai avec une collègue le mardi. Si les horaires ne conviennent pas, je chercherai un autre cours. Je prendrai une décision à la fin du mois.',de:'In sechs Monaten möchte ich eine Ausbildung beginnen. Vor der Anmeldung prüfe ich die Voraussetzungen und den Preis. Ich plane jede Woche zwei Stunden für die Sprache ein und übe dienstags mit einer Kollegin. Falls die Zeiten nicht passen, suche ich einen anderen Kurs. Am Monatsende treffe ich eine Entscheidung.',es:'Dentro de seis meses quiero empezar una formación. Antes de inscribirme voy a comprobar los requisitos y el precio. También dedicaré dos horas por semana al idioma y practicaré los martes con una compañera. Si el horario no me conviene, buscaré otro curso. Tomaré una decisión al final del mes.'}},
{id:'opinion-local-change',level:'b1',section:'foundation',number:11,title:'نظر شخصی و دلیل',passage:{
fr:'La mairie propose de fermer une rue aux voitures chaque dimanche matin pour organiser un marché. Dans une réunion de quartier, Amine soutient l’idée parce qu’elle permettrait aux familles de marcher plus tranquillement. Il donne un exemple : sa fille pourrait aller à vélo jusqu’au marché. Toutefois, sa voisine Claire craint que les personnes âgées aient du mal à accéder aux commerces. Amine reconnaît cette difficulté et suggère de garder un passage pour les véhicules des personnes à mobilité réduite. Les habitants souhaitent essayer la proposition pendant quatre semaines avant de décider si elle doit continuer.',
de:'Die Stadt schlägt vor, eine Straße jeden Sonntagvormittag für Autos zu schließen und dort einen Markt zu veranstalten. Bei einem Nachbarschaftstreffen unterstützt Amine die Idee, weil Familien dann ruhiger zu Fuß gehen könnten. Er nennt ein Beispiel: Seine Tochter könnte mit dem Fahrrad zum Markt fahren. Seine Nachbarin Claire befürchtet jedoch, dass ältere Menschen die Geschäfte schlechter erreichen. Amine erkennt dieses Problem an und schlägt vor, eine Durchfahrt für Fahrzeuge von Menschen mit eingeschränkter Mobilität freizuhalten. Die Anwohner möchten den Vorschlag vier Wochen lang testen, bevor sie über eine Fortsetzung entscheiden.',
es:'El ayuntamiento propone cerrar una calle a los coches cada domingo por la mañana para organizar un mercado. En una reunión del barrio, Amine apoya la idea porque permitiría a las familias caminar con más tranquilidad. Pone un ejemplo: su hija podría ir al mercado en bicicleta. Sin embargo, su vecina Clara teme que a las personas mayores les resulte difícil llegar a las tiendas. Amine reconoce el problema y sugiere mantener un paso para los vehículos de personas con movilidad reducida. Los vecinos quieren probar la propuesta durante cuatro semanas antes de decidir si debe continuar.'},
questions:[{prompt:'دلیل موافقت امین چیست؟',choices:['خانواده‌ها می‌توانند آرام‌تر پیاده‌روی کنند','تمام مغازه‌ها تعطیل می‌شوند','بازار فقط شب‌ها است'],correctIndex:0,explanation:'او به امکان پیاده‌روی آرام‌تر خانواده‌ها اشاره می‌کند.',evidence:{fr:'permettrait aux familles de marcher plus tranquillement',de:'Familien dann ruhiger zu Fuß gehen könnten',es:'permitiría a las familias caminar con más tranquilidad'}},{prompt:'نگرانی همسایه چیست؟',choices:['کمبود دوچرخه','دسترسی دشوارتر سالمندان به مغازه‌ها','نبود جلسهٔ محله'],correctIndex:1,explanation:'او نگران دسترسی افراد مسن به مغازه‌هاست.',evidence:{fr:'les personnes âgées aient du mal à accéder aux commerces',de:'ältere Menschen die Geschäfte schlechter erreichen',es:'a las personas mayores les resulte difícil llegar a las tiendas'}},{prompt:'پیش از تصمیم نهایی چه پیشنهادی مطرح است؟',choices:['اجرای دائمی بدون بررسی','لغو فوری بازار','آزمایش چهار هفته‌ای'],correctIndex:2,explanation:'ساکنان می‌خواهند چهار هفته آزمایش کنند.',evidence:{fr:'essayer la proposition pendant quatre semaines',de:'den Vorschlag vier Wochen lang testen',es:'probar la propuesta durante cuatro semanas'}}],
notes:{fr:{explanation:'برای نظر از «à mon avis» و برای دلیل از «parce que» استفاده کنید؛ یک مثال مشخص استدلال را روشن‌تر می‌کند.',first:'À mon avis, le marché est une bonne idée.',second:'Je soutiens ce projet parce qu’il facilite la marche.',difference:'اولی نظر و دومی دلیل آن است.',phrases:[{text:'à mon avis',meaning:'به نظر من'},{text:'un passage accessible',meaning:'مسیر دسترس‌پذیر'},{text:'faire un essai',meaning:'آزمایش کردن'}]},de:{explanation:'«meiner Meinung nach» نظر و «weil» دلیل را معرفی می‌کند؛ در بند weil فعل صرف‌شده در پایان می‌آید.',first:'Meiner Meinung nach ist der Markt eine gute Idee.',second:'Ich unterstütze das Projekt, weil Familien ruhiger gehen können.',difference:'اولی نظر و دومی دلیل آن است.',phrases:[{text:'meiner Meinung nach',meaning:'به نظر من'},{text:'eine barrierefreie Durchfahrt',meaning:'مسیر دسترس‌پذیر'},{text:'einen Versuch machen',meaning:'آزمایش کردن'}]},es:{explanation:'«en mi opinión» نظر و «porque» دلیل را معرفی می‌کند؛ نگرانی دیگران را بدون اینکه نظر خود را عوض کنید می‌توانید بپذیرید.',first:'En mi opinión, el mercado es una buena idea.',second:'Apoyo el proyecto porque facilita los paseos.',difference:'اولی نظر و دومی دلیل آن است.',phrases:[{text:'en mi opinión',meaning:'به نظر من'},{text:'un paso accesible',meaning:'مسیر دسترس‌پذیر'},{text:'hacer una prueba',meaning:'آزمایش کردن'}]}},
speaking:'دربارهٔ بازار هفتگی نظر دهید، یک دلیل و مثال بیاورید و به نگرانی دسترسی پاسخ دهید.',writing:'در پیام به ساکنان محله نظر خود، دلیل، نگرانی دیگران و پیشنهادی برای آزمایش بیان کنید.',steps:['نظر خود را روشن بنویسید.','یک دلیل و مثال بیاورید.','نگرانی دیگران را بازگو کنید.','راه‌حل و آزمایش پیشنهادی را اضافه کنید.'],model:{fr:'À mon avis, le marché du dimanche est une bonne idée parce que les familles pourront marcher plus tranquillement. Par exemple, les enfants pourront venir à vélo. Je comprends cependant que certaines personnes aient besoin d’un accès en voiture. Nous pourrions garder un passage accessible et essayer le projet pendant quatre semaines avant de décider.',de:'Meiner Meinung nach ist der Sonntagsmarkt eine gute Idee, weil Familien ruhiger zu Fuß gehen können. Kinder könnten zum Beispiel mit dem Fahrrad kommen. Ich verstehe aber, dass manche Menschen einen Zugang mit dem Auto brauchen. Wir könnten eine Durchfahrt freihalten und den Vorschlag vier Wochen lang testen, bevor wir entscheiden.',es:'En mi opinión, el mercado del domingo es una buena idea porque las familias podrán pasear con más tranquilidad. Por ejemplo, los niños podrán venir en bicicleta. Sin embargo, entiendo que algunas personas necesitan acceder en coche. Podríamos mantener un paso accesible y probar el proyecto durante cuatro semanas antes de decidir.'}},
{id:'constructive-feedback',level:'b2',section:'foundation',number:17,title:'بازخورد سازنده دربارهٔ گزارش',passage:{
fr:'Après une présentation, Salomé donne un retour à son collègue Julien. Elle commence par souligner que les graphiques rendent les résultats faciles à comprendre. Elle remarque ensuite que la méthode de collecte n’a pas été expliquée et que le public a posé plusieurs questions à ce sujet. Au lieu de dire que le rapport est mauvais, elle propose d’ajouter une diapositive sur l’origine des données et leurs limites. Julien explique qu’il disposait de peu de temps, mais accepte de préparer cette diapositive. Ils conviennent de la relire ensemble avant la prochaine réunion et de demander à un membre de l’équipe si les explications sont claires.',
de:'Nach einer Präsentation gibt Salomé ihrem Kollegen Julian eine Rückmeldung. Zuerst hebt sie hervor, dass die Grafiken die Ergebnisse leicht verständlich machen. Danach stellt sie fest, dass die Methode der Datenerhebung nicht erklärt wurde und das Publikum dazu mehrere Fragen gestellt hat. Statt den Bericht schlecht zu nennen, schlägt sie vor, eine Folie über die Herkunft und die Grenzen der Daten hinzuzufügen. Julian erklärt, dass ihm wenig Zeit zur Verfügung stand, erklärt sich aber bereit, die Folie vorzubereiten. Sie vereinbaren, sie vor der nächsten Sitzung gemeinsam zu prüfen und ein Teammitglied zu fragen, ob die Erklärungen klar sind.',
es:'Después de una presentación, Salomé da su opinión a su compañero Julián. Primero destaca que los gráficos hacen que los resultados sean fáciles de entender. Después observa que no se explicó el método de recogida de datos y que el público hizo varias preguntas sobre ese punto. En lugar de decir que el informe es malo, propone añadir una diapositiva sobre el origen de los datos y sus límites. Julián explica que tenía poco tiempo, pero acepta preparar la diapositiva. Acuerdan revisarla juntos antes de la próxima reunión y preguntar a una persona del equipo si las explicaciones están claras.'},
questions:[{prompt:'سالومه ابتدا به چه نقطهٔ قوتی اشاره می‌کند؟',choices:['روشن بودن نتایج به کمک نمودارها','حذف همهٔ داده‌ها','مدت طولانی جلسه'],correctIndex:0,explanation:'او ابتدا از نمودارهای روشن تمجید می‌کند.',evidence:{fr:'les graphiques rendent les résultats faciles à comprendre',de:'die Grafiken die Ergebnisse leicht verständlich machen',es:'los gráficos hacen que los resultados sean fáciles de entender'}},{prompt:'چه چیزی دربارهٔ روش داده توضیح داده نشده بود؟',choices:['رنگ نمودار','روش جمع‌آوری داده','نام اعضای جلسه'],correctIndex:1,explanation:'روش جمع‌آوری داده توضیح داده نشده بود.',evidence:{fr:'la méthode de collecte n’a pas été expliquée',de:'die Methode der Datenerhebung nicht erklärt wurde',es:'no se explicó el método de recogida de datos'}},{prompt:'اقدام مشترک پیش از جلسهٔ بعد چیست؟',choices:['حذف ارائه','ارسال گزارش بدون بررسی','مرور اسلاید و پرسیدن نظر یک عضو تیم'],correctIndex:2,explanation:'آنها اسلاید را مرور و روشنی توضیح را از همکار می‌پرسند.',evidence:{fr:'la relire ensemble avant la prochaine réunion',de:'sie vor der nächsten Sitzung gemeinsam zu prüfen',es:'revisarla juntos antes de la próxima reunión'}}],
notes:{fr:{explanation:'بازخورد سازنده یک مشاهدهٔ مشخص، اثر آن و درخواستی قابل اجرا دارد. پیشنهاد مؤدبانه با «on pourrait» از قضاوت دربارهٔ شخص متمایز است.',first:'Les graphiques facilitent la lecture des résultats.',second:'On pourrait préciser comment les données ont été recueillies.',difference:'اولی مشاهدهٔ مثبت و دومی پیشنهاد بهبود است.',phrases:[{text:'donner un retour',meaning:'بازخورد دادن'},{text:'l’origine des données',meaning:'منشأ داده‌ها'},{text:'relire ensemble',meaning:'با هم بازخوانی کردن'}]},de:{explanation:'مشاهده را از قضاوت شخصی جدا کنید؛ «man könnte» پیشنهاد را ملایم می‌کند. اثر مشاهده و گام عملی را مشخص کنید.',first:'Die Grafiken machen die Ergebnisse verständlich.',second:'Man könnte erklären, wie die Daten erhoben wurden.',difference:'اولی مشاهدهٔ مثبت و دومی پیشنهاد بهبود است.',phrases:[{text:'eine Rückmeldung geben',meaning:'بازخورد دادن'},{text:'die Herkunft der Daten',meaning:'منشأ داده‌ها'},{text:'gemeinsam prüfen',meaning:'با هم بررسی کردن'}]},es:{explanation:'مشاهده و اثر آن را بدون حملهٔ شخصی بیان کنید؛ «podríamos» راهی برای پیشنهاد محترمانهٔ اقدام مشترک است.',first:'Los gráficos facilitan la comprensión de los resultados.',second:'Podríamos explicar cómo se recogieron los datos.',difference:'اولی مشاهدهٔ مثبت و دومی پیشنهاد بهبود است.',phrases:[{text:'dar una opinión',meaning:'بازخورد دادن'},{text:'el origen de los datos',meaning:'منشأ داده‌ها'},{text:'revisar juntos',meaning:'با هم بررسی کردن'}]}},
speaking:'برای ارائه‌ای فرضی یک نقطهٔ قوت، یک مشاهدهٔ مشخص، اثر آن و پیشنهاد بهبود بیان کنید و به توضیح طرف مقابل پاسخ دهید.',writing:'پیامی سازنده به همکار بنویسید؛ از قضاوت شخصی پرهیز کنید و پیشنهاد و زمان بازبینی را روشن کنید.',steps:['یک نقطهٔ قوت مشخص بیان کنید.','مشاهده و اثر آن را بدون قضاوت شخصی توضیح دهید.','پیشنهاد عملی بدهید.','برای شنیدن نظر و بازبینی دعوت کنید.'],model:{fr:'Bonjour Julien, les graphiques rendent les résultats très clairs. J’ai remarqué que la méthode de collecte n’était pas expliquée et plusieurs personnes ont posé des questions. On pourrait ajouter une diapositive sur l’origine et les limites des données. Qu’en penses-tu ? Si tu es d’accord, relisons-la ensemble avant la prochaine réunion et demandons un avis à l’équipe.',de:'Hallo Julian, die Grafiken machen die Ergebnisse sehr verständlich. Mir ist aufgefallen, dass die Datenerhebung nicht erklärt wurde und das Publikum mehrere Fragen hatte. Man könnte eine Folie zur Herkunft und zu den Grenzen der Daten ergänzen. Was meinst du? Wenn du einverstanden bist, prüfen wir sie vor der nächsten Sitzung gemeinsam und fragen ein Teammitglied nach seiner Meinung.',es:'Hola, Julián: los gráficos ayudan mucho a entender los resultados. He observado que no se explicó la recogida de datos y que el público hizo varias preguntas. Podríamos añadir una diapositiva sobre el origen y los límites de los datos. ¿Qué te parece? Si estás de acuerdo, revisémosla antes de la próxima reunión y pidamos la opinión de alguien del equipo.'}},
{id:'structured-argument',level:'b2',section:'foundation',number:15,title:'استدلال مرحله‌ای با پاسخ به اعتراض',passage:{
fr:'Une université envisage de rendre obligatoire un court cours de sécurité numérique pour les nouveaux étudiants. Le groupe qui soutient le projet affirme que ce cours aiderait à reconnaître les messages frauduleux. Il cite un exercice interne où plusieurs étudiants ont confondu un faux message avec un message officiel. Des opposants répondent que l’exercice ne prouve pas que le cours réduira les fraudes et que les étudiants ont déjà un emploi du temps chargé. Les partisans proposent donc un essai facultatif, puis une évaluation des connaissances avant et après le cours. Ils reconnaissent qu’il faudra également mesurer le temps demandé et écouter les objections avant toute décision générale.',
de:'Eine Universität überlegt, einen kurzen Kurs zur digitalen Sicherheit für neue Studierende verpflichtend zu machen. Die Gruppe, die das Projekt unterstützt, behauptet, dass der Kurs beim Erkennen betrügerischer Nachrichten helfen würde. Sie verweist auf eine interne Übung, bei der mehrere Studierende eine falsche Nachricht für eine offizielle hielten. Gegner erwidern, dass die Übung nicht beweise, dass der Kurs Betrug reduzieren werde, und dass die Studierenden bereits wenig freie Zeit hätten. Die Befürworter schlagen deshalb einen freiwilligen Test und eine Wissensüberprüfung vor und nach dem Kurs vor. Sie erkennen an, dass auch der Zeitaufwand gemessen und die Einwände vor einer allgemeinen Entscheidung angehört werden müssen.',
es:'Una universidad estudia hacer obligatorio un curso corto de seguridad digital para los estudiantes nuevos. El grupo que apoya el proyecto afirma que el curso ayudaría a reconocer mensajes fraudulentos. Cita un ejercicio interno en el que varios estudiantes confundieron un mensaje falso con uno oficial. Los opositores responden que el ejercicio no demuestra que el curso reduzca los fraudes y que los estudiantes ya tienen poco tiempo libre. Por eso los partidarios proponen una prueba voluntaria y una evaluación de conocimientos antes y después del curso. Reconocen que también habrá que medir el tiempo necesario y escuchar las objeciones antes de tomar una decisión general.'},
questions:[{prompt:'استدلال اصلی موافقان چیست؟',choices:['آموزش ممکن است به شناسایی پیام‌های جعلی کمک کند','تمام تقلب‌ها قبلاً حذف شده‌اند','دانشجویان برنامهٔ خالی دارند'],correctIndex:0,explanation:'موافقان به تشخیص پیام‌های جعلی اشاره می‌کنند.',evidence:{fr:'aiderait à reconnaître les messages frauduleux',de:'beim Erkennen betrügerischer Nachrichten helfen würde',es:'ayudaría a reconocer mensajes fraudulentos'}},{prompt:'اعتراض مخالفان دربارهٔ شواهد چیست؟',choices:['هیچ تمرینی انجام نشده','تمرین ثابت نمی‌کند که دوره تقلب را کاهش می‌دهد','دانشجویان هیچ پیامی ندیده‌اند'],correctIndex:1,explanation:'تمرین داخلی به‌تنهایی اثر دوره بر تقلب را ثابت نمی‌کند.',evidence:{fr:'l’exercice ne prouve pas que le cours réduira les fraudes',de:'die Übung nicht beweise, dass der Kurs Betrug reduzieren werde',es:'el ejercicio no demuestra que el curso reduzca los fraudes'}},{prompt:'پیشنهاد برای بررسی پیش از تصمیم عمومی چیست؟',choices:['اجباری کردن فوری','نادیده گرفتن اعتراض','آزمایش داوطلبانه و سنجش پیش و پس'],correctIndex:2,explanation:'موافقان آزمون داوطلبانه و ارزیابی پیشنهاد می‌کنند.',evidence:{fr:'un essai facultatif, puis une évaluation des connaissances avant et après le cours',de:'einen freiwilligen Test und eine Wissensüberprüfung vor und nach dem Kurs',es:'una prueba voluntaria y una evaluación de conocimientos antes y después del curso'}}],
notes:{fr:{explanation:'استدلال مرحله‌ای شامل ادعا، شاهد، اعتراض، پاسخ و نتیجه است. از «cependant» برای اعتراض و «donc» برای پاسخ یا نتیجهٔ مرتبط استفاده کنید.',first:'Le cours pourrait aider à reconnaître les messages frauduleux.',second:'Cependant, l’exercice ne prouve pas son efficacité.',difference:'اولی ادعای احتمالی و دومی محدودیت شاهد است.',phrases:[{text:'citer un exemple',meaning:'ذکر مثال'},{text:'soulever une objection',meaning:'مطرح کردن اعتراض'},{text:'évaluer les résultats',meaning:'ارزیابی نتیجه‌ها'}]},de:{explanation:'ادعا را با شاهد و سپس اعتراض ارائه کنید؛ «jedoch» محدودیت و «deshalb» پاسخ را متصل می‌کند. «könnte» از قطعیت بی‌جا پرهیز می‌کند.',first:'Der Kurs könnte beim Erkennen falscher Nachrichten helfen.',second:'Die Übung beweist jedoch seine Wirksamkeit nicht.',difference:'اولی ادعای احتمالی و دومی محدودیت شاهد است.',phrases:[{text:'ein Beispiel nennen',meaning:'ذکر مثال'},{text:'einen Einwand vorbringen',meaning:'مطرح کردن اعتراض'},{text:'Ergebnisse auswerten',meaning:'ارزیابی نتیجه‌ها'}]},es:{explanation:'ادعا، شاهد، اعتراض و پاسخ را به هم وصل کنید. «sin embargo» محدودیت و «por eso» اقدام پیشنهادی را معرفی می‌کند.',first:'El curso podría ayudar a reconocer mensajes fraudulentos.',second:'Sin embargo, el ejercicio no demuestra su eficacia.',difference:'اولی ادعای احتمالی و دومی محدودیت شاهد است.',phrases:[{text:'citar un ejemplo',meaning:'ذکر مثال'},{text:'plantear una objeción',meaning:'مطرح کردن اعتراض'},{text:'evaluar los resultados',meaning:'ارزیابی نتیجه‌ها'}]}},
speaking:'موضعی دربارهٔ دورهٔ امنیت دیجیتال ارائه کنید، شاهد و اعتراض را بازگو و راهی برای بررسی پیشنهاد دهید.',writing:'متن استدلالی بنویسید: ادعا، شاهد محدود، نظر مخالف، پاسخ و نتیجهٔ مشروط.',steps:['موضع و دلیل را بنویسید.','شاهد را همراه محدودیت آن ذکر کنید.','اعتراض معتبر را توضیح دهید.','آزمایش و نتیجهٔ مشروط پیشنهاد کنید.'],model:{fr:'À mon avis, une formation courte pourrait aider les nouveaux étudiants à reconnaître les messages frauduleux. L’exercice interne montre une difficulté, mais il ne prouve pas que le cours réduira les fraudes. Les étudiants disposent aussi de peu de temps. Je propose donc un essai facultatif avec une évaluation avant et après le cours. Une décision générale devrait attendre les résultats et les retours des participants.',de:'Meiner Meinung nach könnte ein kurzer Kurs neuen Studierenden helfen, betrügerische Nachrichten zu erkennen. Die interne Übung zeigt eine Schwierigkeit, beweist aber nicht, dass der Kurs Betrug reduziert. Die Studierenden haben zudem wenig Zeit. Deshalb schlage ich einen freiwilligen Test mit einer Überprüfung vor und nach dem Kurs vor. Eine allgemeine Entscheidung sollte die Ergebnisse und die Rückmeldungen berücksichtigen.',es:'En mi opinión, un curso corto podría ayudar a los estudiantes nuevos a reconocer mensajes fraudulentos. El ejercicio interno muestra una dificultad, pero no demuestra que el curso reduzca los fraudes. Además, los estudiantes disponen de poco tiempo. Por eso propongo una prueba voluntaria con una evaluación antes y después. La decisión general debería esperar los resultados y las opiniones de los participantes.'}},
];
